L000539	
L000540	\mysec{Appendix B: Pad\'e Approximant Spectroscopy}\label{pade}Our construction is closely related to the methodology of Pad\'e approximants~\cite{Nuttall,Sokolovski:2011odo,PEROTTI201895}.
L000541	Let us define the paradiagonal Pad\'e approximant of order $[(\ell+r-1)/\ell]$ to the function $Q(s)$ as   $P(s) =N(s)/D(s)$
L000542	for polynomials $N(s)$ and $D(s)$ of degree $\ell+r-1$ and $\ell$, respectively.
L000543	We then have by definition $D(s)Q(s)-N(s)=O(s^{2\ell+r})$.
L000544	For convenience, let us assume that $Q(s)$ is regular at $s=0$; the analogous construction with a massless pole is straightforward.
L000545	Writing
L000546	\eq{
L000547	\hat Q(s) = \frac{Q(s)-\sum_{k=0}^{r-1}c_{k}s^{k}}{s^r} = \sum_{k=0}^{\infty} c_{k+r}s^k,
L000548	}{}
L000549	the Pad\'e approximant to $\hat Q(s)$ of order $[(\ell-1)/\ell]$ has the same denominator $D(s)$, since \be
L000550	\hat D(s)Q(s)-\hat D(s)\sum_{k=0}^{r-1}c_{k}s^{k}-s^{r}\hat N(s)=O(s^{2\ell+r})
L000551	\ee
L000552	implies that $\hat D(s) = D(s)$.
L000553	Writing the expansion $\hat D(s) = \sum_{j=0}^{\ell}d_{j}s^{j}$ and matching the coefficient of $s^{\ell},s^{\ell+1},\ldots,s^{2\ell-1}$ in $D(s)\hat Q(s) = \hat N(s)+O(s^{2\ell})$ gives the Pad\'e condition
L000554	\eq{
L000555	\sum_{j=0}^{\ell}c_{r+i+\ell-j}d_{j}=0,\quad i=0,\ldots,\ell-1.
L000556	}{eq:pade_system}
L000557	Let $1/y$ be a zero of $\hat D(s)$.
L000558	Then $\hat D(s)/(1-ys)$ is a polynomial whose expansion we can write as $\sum_{j=0}^{\ell-1}e_{\ell-1-j}s^{j}$. Equating the two expansions of $\hat D(s)$, we have
L000559	\begin{equation}
L000560	\begin{aligned}
L000561	d_{0}&=e_{\ell-1},\qquad d_{\ell}= -ye_{0},\\
L000562	d_{j}&=e_{\ell-1-j}-ye_{\ell-j},\;\;1\leq j\leq \ell-1.
L000563	\end{aligned}\label{eq:dexp}
L000564	\end{equation}
L000565	Substituting these relations into \Eq{eq:pade_system}, we have $\sum_{j=0}^{\ell-1}\left(c_{r+1+i+j}- yc_{r+i+j}\right)e_{j}=0$,
L000566	or in matrix form,
L000567	\be
L000568	[({\bf c}_{r+1}^{(\ell)}-y {\bf c}_{r}^{(\ell)}){\bf e}]_{i}=0,\label{eq:matrixey}
L000569	\ee
L000570	so ${\bf e}$ is an eigenvector of ${\bf c}_{r+1}^{(\ell)}-y{\bf c}_{r}^{(\ell)}$
L000571	with zero eigenvalue, which implies
L000572	\be
L000573	\det({\bf c}_{r+1}^{(\ell)}-y{\bf c}_{r}^{(\ell)})=0.
L000574	\ee
L000575	Conversely, suppose we have a solution $y$ of Eq.~\eqref{eq:matrixey} for some eigenvector ${\bf e}$.  We can construct a polynomial $\tilde D(s) = (1-ys)\sum_{j=0}^{\ell-1}e_{\ell-1-j} s^j = \sum_{j=0}^\ell \tilde d_j s^j$.
L000576	By inspection, we see that the algebraic relations between $\tilde d_j$ and $e_j$ are precisely those satisfied by $d_j$ in Eq.~\eqref{eq:dexp}, so $d_j = \tilde d_j$ and $\tilde D(s) = \hat D(s)$.
L000577	Since $1/y$ is a zero of $\tilde D(s)$ by construction, we have $\hat D(1/y)=0$ as well.
L000578	Thus, the solutions
L000579	$\lambda^{(\ell)}$ of the truncated Hankel matrix problem in Eq.~\eqref{char_eq_trunc} are precisely the inverses
L000580	of the poles of the Pad\'e approximant to $Q(s)$ of order $[(\ell+r-1)/\ell]$.
